#include <bits/stdc++.h>
using namespace std;
#define int long long
const int MOD_A=998244353;
const int MOD_B=1000000007;
int result;
int n_value;
int counter1;
vector<int> digitValues[7];
int sumValues[7];
void buildValues(int depth,int prefixSum){
	if(depth==7) return;
	digitValues[depth].push_back((counter1 - prefixSum + MOD_A) % MOD_A);
	sumValues[depth] += (counter1 - prefixSum + MOD_A) % MOD_A;
	counter1++;
	for(int d=0; d<=9; ++d){
		buildValues(depth+1, prefixSum*10+d);
	}
}
bool inRange(int x){
	const int half=1000000;
	return x*half+999999 <= n_value && x*half*10 > n_value;
}
int count2_local;
int powTen[7]={1,10,100,1000,10000,100000,1000000};
void traverse(int level,int num){
	if(num > n_value) return;
	if(inRange(num)){
		for(int i=0; i<=6; ++i){
			int offset = ((count2_local+1 - (num*powTen[i])) % MOD_A + MOD_A) % MOD_A;
			int pos = lower_bound(digitValues[i].begin(), digitValues[i].end(), MOD_A - offset) - digitValues[i].begin();
			result += (sumValues[i] + offset * (int)digitValues[i].size() - MOD_A * ((int)digitValues[i].size() - pos)) % MOD_B;
			result %= MOD_B;
		}
		count2_local += counter1;
	}
	else{
		count2_local++;
		result += ((count2_local - num) % MOD_A + MOD_A) % MOD_A;
		result %= MOD_B;
		for(int d=0; d<=9; ++d){
			if(level==0 && d==0) continue;
			traverse(level+1, num*10+d);
		}
	}
}
int main(){
	cin >> n_value;
	buildValues(0,0);
	for(int i=0; i<=6; ++i) sort(digitValues[i].begin(), digitValues[i].end());
	count2_local = -1;
	traverse(0,0);
	cout << result << "\n";
}
